#!/usr/bin/env node
/**
 * The command. `node src/cli.js waves`, `node src/cli.js explain` and
 * `node src/cli.js pack <workers>` each report on the build graph read from
 * standard input.
 */
import { readFileSync } from 'node:fs'
import { parseGraph, findCycle, schedule } from './graph.js'
import { pack } from './pack.js'

function fail(msg, code = 2) {
  process.stderr.write(`${msg}\n`)
  process.exit(code)
}

const args = process.argv.slice(2)
const mode = args[0]
let workers = 0
if (mode === 'waves' || mode === 'explain') {
  if (args.length !== 1) fail('error: usage: cli.js waves|explain|pack <workers>')
} else if (mode === 'pack') {
  if (args.length !== 2) fail('error: usage: cli.js waves|explain|pack <workers>')
  if (!/^[1-9][0-9]*$/.test(args[1])) fail('error: workers must be a positive integer')
  workers = Number(args[1])
} else {
  fail('error: usage: cli.js waves|explain|pack <workers>')
}

let input = ''
try {
  input = readFileSync(0, 'utf8')
} catch {
  input = ''
}

let graph
try {
  graph = parseGraph(input)
} catch (e) {
  if (e && e.cliMessage) fail(e.cliMessage)
  throw e
}
const cycle = findCycle(graph)
if (cycle) fail(`error: cycle: ${cycle.join(' -> ')}`, 3)

const names = [...graph.costs.keys()].sort()
const { start, finish, depth, total } = schedule(graph, names)
