export function pack({ costs, deps }, names, workers) {
  const dependents = new Map(names.map((n) => [n, []]))
  for (const n of names) for (const d of deps.get(n)) dependents.get(d).push(n)
  // priority: longest chain starting at each task
  const prio = new Map()
  const order = []
  const seen = new Set()
  for (const root of names) {
    const stack = [root]
    while (stack.length) {
      const n = stack[stack.length - 1]
      if (seen.has(n)) {
        stack.pop()
        continue
      }
      const pend = dependents.get(n).filter((d) => !prio.has(d))
      if (pend.length) {
        stack.push(...pend)
        continue
      }
      let best = 0n
      for (const d of dependents.get(n)) if (prio.get(d) > best) best = prio.get(d)
      prio.set(n, best + costs.get(n))
      seen.add(n)
      order.push(n)
      stack.pop()
    }
  }
  const finish = new Map()
  const freeAt = new Array(workers).fill(0n)
  const ran = Array.from({ length: workers }, () => [])
  const waiting = new Set(names)
  let remaining = new Map(names.map((n) => [n, deps.get(n).length]))
  let ready = names.filter((n) => remaining.get(n) === 0)
  let t = 0n
  let makespan = 0n
  while (waiting.size) {
    for (;;) {
      let w = freeAt.findIndex((f) => f <= t)
      if (w < 0 || !ready.length) break
      let bi = 0
      for (let i = 1; i < ready.length; i++) {
        const a = ready[i]
        const b = ready[bi]
        if (prio.get(a) > prio.get(b) || (prio.get(a) === prio.get(b) && a < b)) bi = i
      }
      const n = ready[bi]
      ready.splice(bi, 1)
      waiting.delete(n)
      const f = t + costs.get(n)
      finish.set(n, f)
      freeAt[w] = f
      ran[w].push(`${n}@${t}-${f}`)
      if (f > makespan) makespan = f
      if (f <= t) {
        for (const d of dependents.get(n)) {
          remaining.set(d, remaining.get(d) - 1)
          if (remaining.get(d) === 0) ready.push(d)
        }
      }
    }
    if (!waiting.size) break
    // advance to next finish instant; release dependents of tasks finishing then
    let next = null
    for (const f of finish.values()) if (f > t && (next === null || f < next)) next = f
    t = next
    for (const [n, f] of finish) {
      if (f === t) {
        for (const d of dependents.get(n)) {
          remaining.set(d, remaining.get(d) - 1)
          if (remaining.get(d) === 0) ready.push(d)
        }
      }
    }
  }
  let out = ''
  ran.forEach((r, i) => {
    out += `worker ${i}:${r.map((x) => ' ' + x).join('')}\n`
  })
  return out + `makespan ${makespan}\n`
}
